<script setup>
import {ref,computed,watch,onMounted,onUnmounted} from 'vue';import {t,dateTime,fixed} from './i18n.js';import WaferMap from './WaferMap.vue';import InspectionPanel from './InspectionPanel.vue';
const props=defineProps({api:Function,equipmentId:String,waferId:{type:String,default:''},user:Object});
const rows=ref([]),station=ref(null),current=ref(null),comparison=ref(null),compareId=ref(''),mode=ref('thickness'),page=ref(0),error=ref(false),busy=ref(false);let timer,active=true,epoch=0;
const canChange=computed(()=>['Engineer','Leader'].includes(props.user?.role));
const compatible=computed(()=>!comparison.value||current.value?.result?.modelVersion===comparison.value?.result?.modelVersion&&current.value?.result?.coordinates===comparison.value?.result?.coordinates);
const maps=computed(()=>[current.value,compatible.value?comparison.value:null].filter(v=>v?.result));const low=computed(()=>Math.min(...maps.value.map(v=>v.result.minNm)));const high=computed(()=>Math.max(...maps.value.map(v=>v.result.maxNm)));
async function load(){const n=++epoch;try{const [r,s]=await Promise.all([props.api('/metrology/runs?equipmentId='+encodeURIComponent(props.equipmentId)+'&waferId='+encodeURIComponent(props.waferId)+'&page='+page.value),props.api('/metrology/station')]);if(!active||n!==epoch)return;rows.value=r;station.value=s;error.value=false;if(current.value){const detail=await props.api('/metrology/runs/'+current.value.id);if(active&&n===epoch)current.value=detail;}}catch{if(active&&n===epoch)error.value=true;}}
async function select(id){comparison.value=null;compareId.value='';try{current.value=await props.api('/metrology/runs/'+id);}catch{error.value=true;}}
async function compare(){if(!compareId.value){comparison.value=null;return;}try{comparison.value=await props.api('/metrology/runs/'+compareId.value);}catch{error.value=true;}}
let retryKey='';async function action(type){if(busy.value)return;busy.value=true;try{retryKey||=crypto.randomUUID();await props.api('/metrology/runs/'+current.value.id+'/'+type,{method:'POST',body:JSON.stringify({requestId:retryKey})});retryKey='';await load();}catch{error.value=true;}finally{busy.value=false;}}
watch(()=>[props.equipmentId,props.waferId],()=>{current.value=null;comparison.value=null;page.value=0;load();});watch(page,load);onMounted(()=>{load();timer=setInterval(load,5000);});onUnmounted(()=>{active=false;epoch++;clearInterval(timer);});
</script>
<template><section class="metrology"><div class="kla-header"><h3>{{t('kla_title')}}</h3><button @click="load">{{t('kla_refresh')}}</button></div><p>{{t('kla_synthetic')}} · {{t('kla_retention')}}</p><p v-if="station">{{station.stationId}} · {{t(!station.enabled?'kla_disabled':station.station?.fresh?'kla_online':'kla_offline')}} <span v-for="q in station.queue" :key="q.state"> · {{t('kla_'+q.state)}} {{q.count}}</span></p><p v-if="error" role="alert">{{t('kla_error')}}</p><div class="kla-list"><button v-for="r in rows" :key="r.id" @click="select(r.id)" :class="{chosen:current?.id===r.id}"><b>{{r.wafer_id}}</b> · {{t('kla_revision')}} {{r.revision}} · {{t('kla_'+r.state)}} <strong v-if="r.alarm"> · {{t('kla_review')}}</strong></button><p v-if="!rows.length">{{t('kla_empty')}}</p></div><div class="kla-header"><button :disabled="page===0" @click="page--">{{t('kla_previous')}}</button><button :disabled="rows.length<50" @click="page++">{{t('kla_next')}}</button></div><article v-if="current"><h4>{{current.source.equipmentId}} · {{current.source.pm}} · {{current.wafer_id}}</h4><p>{{current.source.processRunId}} · {{current.source.recipeVersion}}</p><p>{{t('kla_date')}} {{dateTime(current.completed_at)}}</p><div class="kla-header" v-if="canChange"><button :disabled="busy||current.expired||!['completed','awaiting-remeasure'].includes(current.state)" @click="action('remeasure')">{{t('kla_remeasure')}}</button><button v-if="current.alarm&&!current.acknowledged" :disabled="busy" @click="action('acknowledge')">{{t('kla_ack')}}</button></div><p v-if="current.failure_reason">{{t('kla_'+current.failure_reason)}}</p><p v-if="current.expired">{{t('kla_expired')}}</p><template v-else-if="current.result"><p v-if="current.alarm">{{t('kla_reason')}}: {{current.result.thicknessQuality==='review'?t('kla_thickness'):''}} {{current.result.defectQuality==='review'?t('kla_defects'):''}}</p><div class="kla-header" role="tablist"><button v-for="m in ['thickness','defects']" :key="m" role="tab" :aria-selected="mode===m" @click="mode=m">{{t('kla_'+m)}}</button></div><label>{{t('kla_compare')}}<select v-model="compareId" @change="compare"><option value="">{{t('kla_none')}}</option><option v-for="r in rows.filter(r=>r.wafer_id===current.wafer_id&&r.id!==current.id&&r.state==='completed'&&!r.expired)" :value="r.id">{{r.id}} · {{t('kla_revision')}} {{r.revision}}</option></select></label><p v-if="!compatible">{{t('kla_incompatible')}}</p><div class="kla-maps"><div v-for="r in maps" :key="r.id"><p>{{t('kla_revision')}} {{r.revision}} · {{t('kla_'+r.result.quality)}}</p><p>{{t('kla_mean')}} {{fixed(r.result.meanNm,3)}} nm · {{t('kla_min')}} {{fixed(r.result.minNm,3)}} · {{t('kla_max')}} {{fixed(r.result.maxNm,3)}} · {{t('kla_uniformity')}} {{fixed(r.result.uniformityPct,2)}}%</p><WaferMap :key="r.id+mode" :result="r.result" :mode="mode" :low="low" :high="high"/></div></div></template><p v-else>{{t('kla_pending')}}</p><InspectionPanel :api="api" :measurement-id="current.id" :user="user"/></article></section></template>
<style scoped>.metrology{margin:20px 0;padding:20px;border:1px solid var(--border);border-radius:12px;min-width:0}.metrology p{overflow-wrap:anywhere;font-size:13px}.kla-header{display:flex;gap:12px;align-items:center;justify-content:space-between;flex-wrap:wrap;margin:12px 0}.kla-list{display:grid;gap:6px;max-height:260px;overflow:auto}.kla-list button{text-align:left;overflow-wrap:anywhere}.chosen{border-color:var(--fg);background:var(--surface-alt)}.kla-list strong{color:#ae582e}.kla-maps{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,300px),1fr));gap:20px}.metrology select{max-width:100%;width:100%}.metrology article{min-width:0}@media(max-width:600px){.metrology{padding:12px}}</style>
